; Auto-generated by scripts/generate-palette-transitions.js from src/games/smb/palettes/.
; Do not edit by hand -- regenerate instead.
;
; Every palette has one fixed IIgs slot layout: the IIgs palette 0 slot that each of the 32 NES
; palette RAM entries ($3F00-$3F1F) is shown in.  The layouts are chosen together, so that the
; background groups that keep the same slots across the transitions don't need their tiles
; redrawn (a group whose slots change has to be recompiled with the new swizzle table).
;
; Requires: NES_ColorToIIgs_X, NES_SetPaletteMap, RefreshPPUAttributesL, PPU_SetPaletteWritesL,
;           ppuPalDirty, _ppumask, PPU_MEM, SHR_PALETTES

; Swizzle tables, in the PALDATA segment (palettes.s)
PAL_GROUND_SWIZZLE EXT
PAL_UNDERGROUND_SWIZZLE EXT
PAL_WATER_SWIZZLE EXT
PAL_CASTLE_SWIZZLE EXT
PAL_GROUND_SNOW_SWIZZLE EXT
PAL_GROUND_MUSHROOM_SWIZZLE EXT
PAL_CASTLE_BOWSER_SWIZZLE EXT

; The palette ids (PAL_*) and pinned slots (PAL_SLOT_*) are in pal_defs.s.

; Layouts (NES color -> [slots] per group; *reserved, ~shown as):
;   ground
;     BG0 $22 $29 $1A $0F -> [0,1,2,3]
;     BG1 $22 $36 $17 $0F -> [0,4,5,6]
;     BG2 $22 $30 $21 $0F -> [0,7,8,6]
;     BG3 $22 *$27 $17 $0F -> [0,10,9,6]
;     SP0 $22 *$16 $27 *$18 -> [0,11,13,12]
;     SP1 $22 $1A $30 $27 -> [0,2,7,13]
;     SP2 $22 $16 $30 $27 -> [0,14,7,13]
;     SP3 $22 $0F $36 $17 -> [0,3,4,5]
;   underground
;     BG0 $0F $29 $1A $09 -> [0,1,2,3]
;     BG1 $0F $3C $1C $0F -> [0,4,6,0]
;     BG2 $0F $30 $21 $1C -> [0,7,8,6]
;     BG3 $0F *$27 $17 $1C -> [0,10,9,6]
;     SP0 $0F *$16 $27 *$18 -> [0,11,5,12]
;     SP1 $0F $1C $36 $17 -> [0,6,13,9]
;     SP2 $0F $16 $30 $27 -> [0,14,7,5]
;     SP3 $0F $0C $3C $1C -> [0,15,4,6]
;   water
;     BG0 $22 $15 $12 $25 -> [0,1,2,3]
;     BG1 $22 $3A $1A $0F -> [0,4,5,6]
;     BG2 $22 $30 $12 $0F -> [0,7,8,6]
;     BG3 $22 *$27 $12 $0F -> [0,10,9,6]
;     SP0 $22 *$16 $27 *$18 -> [0,11,13,12]
;     SP1 $22 $10 $30 $27 -> [0,14,7,13]
;     SP2 $22 $16 $30 $27 -> [0,15,7,13]
;     SP3 $22 $0F $30 $10 -> [0,6,7,14]
;   castle
;     BG0 $0F $30 $10 $00 -> [0,1,2,3]
;     BG1 $0F $30 $10 $00 -> [0,4,5,6]
;     BG2 $0F $30 $16 $00 -> [0,7,8,6]
;     BG3 $0F *$27 $17 $00 -> [0,10,9,6]
;     SP0 $0F *$16 $27 *$18 -> [0,11,13,12]
;     SP1 $0F $1C $36 $17 -> [0,14,15,9]
;     SP2 $0F $16 $30 $27 -> [0,8,1,13]
;     SP3 $0F $00 $30 $10 -> [0,3,1,2]
;   ground_snow
;     BG0 $22 $30 $00 $10 -> [0,1,2,3]
;     BG1 $22 $36 $17 $0F -> [0,4,5,6]
;     BG2 $22 $30 $21 $0F -> [0,7,8,6]
;     BG3 $22 *$27 $17 $0F -> [0,10,9,6]
;     SP0 $22 *$16 $27 *$18 -> [0,11,13,12]
;     SP1 $22 $1A $30 $27 -> [0,14,1,13]
;     SP2 $22 $16 $30 $27 -> [0,15,1,13]
;     SP3 $22 $0F $36 $17 -> [0,6,4,5]
;   ground_mushroom
;     BG0 $22 $27 $16 $0F -> [0,1,2,3]
;     BG1 $22 $36 $17 $0F -> [0,4,5,6]
;     BG2 $22 $30 $21 $0F -> [0,7,8,6]
;     BG3 $22 *$27 $17 $0F -> [0,10,9,6]
;     SP0 $22 *$16 $27 *$18 -> [0,11,1,12]
;     SP1 $22 $1A $30 $27 -> [0,13,7,1]
;     SP2 $22 $16 $30 $27 -> [0,2,7,1]
;     SP3 $22 $0F $36 $17 -> [0,3,4,5]
;   castle_bowser
;     BG0 $0F $30 $10 $00 -> [0,1,2,3]
;     BG1 $0F $30 $10 $00 -> [0,4,5,6]
;     BG2 $0F $30 $16 $00 -> [0,7,8,6]
;     BG3 $0F *$27 $17 $00 -> [0,10,9,6]
;     SP0 $0F *$16 $27 *$18 -> [0,11,13,12]
;     SP1 $0F $1A $30 $27 -> [0,14,1,13]
;     SP2 $0F $16 $30 $27 -> [0,8,1,13]
;     SP3 $0F $00 $30 $10 -> [0,3,1,2]

            mx    %00

palCurrent  dw    0                   ; PAL_* id of the palette on screen (0 = none yet)

; SetDefaultPalette
;
; Before the game uploads a palette: the swizzle tables are ground's, and so is the layout of the colors
; shown until the game's palette is detected.
; Called by the game's InitPlayfield (NES_StartUp) and at start-up.
SetDefaultPalette
            ldy   #PAL_GROUND
            sty   palCurrent
            jsr   PalSetWrites        ; Y = palette id
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jmp   NES_SetPaletteMap

; ApplyPaletteChange
;
; The game's PRE_RENDER hook (jsl), on the GS task.  If the palette RAM changed (ppuPalDirty, set by the
; engine's palette write handler), identify the palette in it and switch to it, or show its changed
; colors in the current palette's layout (fades, color cycling, an unknown palette).  While the
; background is off, the game is rebuilding the screen: the old colors stay on whatever is left on it,
; and the new ones come with the new screen.
ApplyPaletteChange
            ldal  ppuPalDirty
            beq   :none
            ldal  _ppumask
            and   #NES_PPUMASK_BG
            beq   :none
            lda   #0
            stal  ppuPalDirty         ; (first, so a write from here on is seen next time)
            ldx   palCurrent
            jsr   DetectNESPalette    ; A = Y = palette id, 0 if none
            beq   :colors             ; not a known palette (e.g. a step of a fade)
            cmp   palCurrent
            beq   :colors
            ldx   palCurrent
            sty   palCurrent
            jsr   UpdatePalette       ; X = from, Y = to
            rtl
:colors     ldy   palCurrent
            beq   :none               ; no palette yet
            jsr   LoadPaletteColors
:none       rtl

; PalSetWrites
;
; Y = palette id (kept).  The palette RAM writes that go straight to their IIgs slot while it is on
; screen (its [direct] cells); the rest mark the palette dirty.  The palettes with the same [direct]
; slots share a table, and it is only installed when it changes.
PalSetWrites
            lda   PAL_WRITES,y
            cmp   palWrites
            beq   :same
            sta   palWrites
            phy
            ldx   #^PAL_WRITES
            jsl   PPU_SetPaletteWritesL
            ply
:same       rts

palWrites   dw    0                   ; The table installed (0: the engine's, every write marking dirty)

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply
            jsr   PalSetWrites        ; Y = palette id

            jsr   LoadPaletteColors
            pla
            jsl   RefreshPPUAttributesL   ; (in the engine bank: ppu_entry.s)
            rts

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #16
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_GROUND_MATCH
            dw    PAL_UNDERGROUND_MATCH
            dw    PAL_WATER_MATCH
            dw    PAL_CASTLE_MATCH
            dw    PAL_GROUND_SNOW_MATCH
            dw    PAL_GROUND_MUSHROOM_MATCH
            dw    PAL_CASTLE_BOWSER_MATCH
PAL_GROUND_MATCH
            db    $29,$1A,$0F,$36,$17,$0F,$30,$21,$0F,$FF,$17,$0F   ; BG0-BG3
            db    $FF,$27,$FF,$1A,$30,$27,$16,$30,$27,$0F,$36,$17   ; SP0-SP3
PAL_UNDERGROUND_MATCH
            db    $29,$1A,$09,$3C,$1C,$0F,$30,$21,$1C,$FF,$17,$1C   ; BG0-BG3
            db    $FF,$27,$FF,$1C,$36,$17,$16,$30,$27,$0C,$3C,$1C   ; SP0-SP3
PAL_WATER_MATCH
            db    $15,$12,$25,$3A,$1A,$0F,$30,$12,$0F,$FF,$12,$0F   ; BG0-BG3
            db    $FF,$27,$FF,$10,$30,$27,$16,$30,$27,$0F,$30,$10   ; SP0-SP3
PAL_CASTLE_MATCH
            db    $30,$10,$00,$30,$10,$00,$30,$16,$00,$FF,$17,$00   ; BG0-BG3
            db    $FF,$27,$FF,$1C,$36,$17,$16,$30,$27,$00,$30,$10   ; SP0-SP3
PAL_GROUND_SNOW_MATCH
            db    $30,$00,$10,$36,$17,$0F,$30,$21,$0F,$FF,$17,$0F   ; BG0-BG3
            db    $FF,$27,$FF,$1A,$30,$27,$16,$30,$27,$0F,$36,$17   ; SP0-SP3
PAL_GROUND_MUSHROOM_MATCH
            db    $27,$16,$0F,$36,$17,$0F,$30,$21,$0F,$FF,$17,$0F   ; BG0-BG3
            db    $FF,$27,$FF,$1A,$30,$27,$16,$30,$27,$0F,$36,$17   ; SP0-SP3
PAL_CASTLE_BOWSER_MATCH
            db    $30,$10,$00,$30,$10,$00,$30,$16,$00,$FF,$17,$00   ; BG0-BG3
            db    $FF,$27,$FF,$1A,$30,$27,$16,$30,$27,$00,$30,$10   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_GROUND_SUCC
            dw    PAL_UNDERGROUND_SUCC
            dw    PAL_WATER_SUCC
            dw    PAL_CASTLE_SUCC
            dw    PAL_GROUND_SNOW_SUCC
            dw    PAL_GROUND_MUSHROOM_SUCC
            dw    PAL_CASTLE_BOWSER_SUCC
PAL_NONE_SUCC
            dw    0
PAL_GROUND_SUCC
            dw    PAL_UNDERGROUND,PAL_WATER,PAL_CASTLE,PAL_GROUND_SNOW,PAL_GROUND_MUSHROOM,0
PAL_UNDERGROUND_SUCC
            dw    PAL_GROUND,PAL_GROUND_SNOW,PAL_GROUND_MUSHROOM,PAL_WATER,PAL_CASTLE,0
PAL_WATER_SUCC
            dw    PAL_GROUND,PAL_GROUND_SNOW,PAL_GROUND_MUSHROOM,PAL_UNDERGROUND,PAL_CASTLE,0
PAL_CASTLE_SUCC
            dw    PAL_CASTLE_BOWSER,PAL_GROUND,PAL_GROUND_SNOW,PAL_GROUND_MUSHROOM,PAL_UNDERGROUND,PAL_WATER,0
PAL_GROUND_SNOW_SUCC
            dw    PAL_GROUND,PAL_UNDERGROUND,PAL_WATER,PAL_CASTLE,PAL_GROUND_MUSHROOM,0
PAL_GROUND_MUSHROOM_SUCC
            dw    PAL_GROUND,PAL_UNDERGROUND,PAL_WATER,PAL_CASTLE,PAL_GROUND_SNOW,0
PAL_CASTLE_BOWSER_SUCC
            dw    PAL_CASTLE,PAL_GROUND,PAL_GROUND_SNOW,PAL_GROUND_MUSHROOM,PAL_UNDERGROUND,PAL_WATER,0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_GROUND_SWIZZLE
            dw    PAL_UNDERGROUND_SWIZZLE
            dw    PAL_WATER_SWIZZLE
            dw    PAL_CASTLE_SWIZZLE
            dw    PAL_GROUND_SNOW_SWIZZLE
            dw    PAL_GROUND_MUSHROOM_SWIZZLE
            dw    PAL_CASTLE_BOWSER_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_GROUND_SWIZZLE
            dw    ^PAL_UNDERGROUND_SWIZZLE
            dw    ^PAL_WATER_SWIZZLE
            dw    ^PAL_CASTLE_SWIZZLE
            dw    ^PAL_GROUND_SNOW_SWIZZLE
            dw    ^PAL_GROUND_MUSHROOM_SWIZZLE
            dw    ^PAL_CASTLE_BOWSER_SWIZZLE

; id -> palette RAM writes: for each entry, the IIgs slot * 2 its writes go to straight away while
; the palette is on screen ([direct] cells), or $FFFF: they mark the palette dirty (PPU_SetPaletteWritesL).
; One table per distinct set of [direct] slots.
PAL_WRITES
            dw    0
            dw    PAL_WRITES_0   ; ground
            dw    PAL_WRITES_0   ; underground
            dw    PAL_WRITES_0   ; water
            dw    PAL_WRITES_0   ; castle
            dw    PAL_WRITES_0   ; ground_snow
            dw    PAL_WRITES_0   ; ground_mushroom
            dw    PAL_WRITES_0   ; castle_bowser
PAL_WRITES_0   ; ground, underground, water, castle, ground_snow, ground_mushroom, castle_bowser
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$14,$FFFF,$FFFF
            dw    $FFFF,$16,$FFFF,$18,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_GROUND_CELLS
            dw    PAL_UNDERGROUND_CELLS
            dw    PAL_WATER_CELLS
            dw    PAL_CASTLE_CELLS
            dw    PAL_GROUND_SNOW_CELLS
            dw    PAL_GROUND_MUSHROOM_CELLS
            dw    PAL_CASTLE_BOWSER_CELLS
PAL_GROUND_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$1A,$18,$FF,$04,$0E,$1A,$FF,$1C,$0E,$1A,$FF,$06,$08,$0A   ; SP0-SP3
PAL_UNDERGROUND_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0C,$FF,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$0A,$18,$FF,$0C,$1A,$12,$FF,$1C,$0E,$0A,$FF,$1E,$08,$0C   ; SP0-SP3
PAL_WATER_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$1A,$18,$FF,$1C,$0E,$1A,$FF,$1E,$0E,$1A,$FF,$0C,$0E,$1C   ; SP0-SP3
PAL_CASTLE_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$1A,$18,$FF,$1C,$1E,$12,$FF,$10,$02,$1A,$FF,$06,$02,$04   ; SP0-SP3
PAL_GROUND_SNOW_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$1A,$18,$FF,$1C,$02,$1A,$FF,$1E,$02,$1A,$FF,$0C,$08,$0A   ; SP0-SP3
PAL_GROUND_MUSHROOM_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$02,$18,$FF,$1A,$0E,$02,$FF,$04,$0E,$02,$FF,$06,$08,$0A   ; SP0-SP3
PAL_CASTLE_BOWSER_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$0C,$FF,$14,$12,$0C   ; BG0-BG3
            db    $FF,$16,$1A,$18,$FF,$1C,$02,$1A,$FF,$10,$02,$1A,$FF,$06,$02,$04   ; SP0-SP3

; from id -> its row of to id -> background groups to redraw (bit 0 = BG0 .. bit 3 = BG3).
; From no palette (0), everything is redrawn.
BG_UPDATE_MASKS
            dw    BG_UPDATE_MASKS_NONE
            dw    BG_UPDATE_MASKS_GROUND
            dw    BG_UPDATE_MASKS_UNDERGROUND
            dw    BG_UPDATE_MASKS_WATER
            dw    BG_UPDATE_MASKS_CASTLE
            dw    BG_UPDATE_MASKS_GROUND_SNOW
            dw    BG_UPDATE_MASKS_GROUND_MUSHROOM
            dw    BG_UPDATE_MASKS_CASTLE_BOWSER
BG_UPDATE_MASKS_NONE
            dw    $0000,%1111,%1111,%1111,%1111,%1111,%1111,%1111
BG_UPDATE_MASKS_GROUND
            dw    $0000
            dw    %0000   ; to ground
            dw    %0010   ; to underground
            dw    %0000   ; to water
            dw    %0000   ; to castle
            dw    %0000   ; to ground_snow
            dw    %0000   ; to ground_mushroom
            dw    %0000   ; to castle_bowser
BG_UPDATE_MASKS_UNDERGROUND
            dw    $0000
            dw    %0010   ; to ground
            dw    %0000   ; to underground
            dw    %0010   ; to water
            dw    %0010   ; to castle
            dw    %0010   ; to ground_snow
            dw    %0010   ; to ground_mushroom
            dw    %0010   ; to castle_bowser
BG_UPDATE_MASKS_WATER
            dw    $0000
            dw    %0000   ; to ground
            dw    %0010   ; to underground
            dw    %0000   ; to water
            dw    %0000   ; to castle
            dw    %0000   ; to ground_snow
            dw    %0000   ; to ground_mushroom
            dw    %0000   ; to castle_bowser
BG_UPDATE_MASKS_CASTLE
            dw    $0000
            dw    %0000   ; to ground
            dw    %0010   ; to underground
            dw    %0000   ; to water
            dw    %0000   ; to castle
            dw    %0000   ; to ground_snow
            dw    %0000   ; to ground_mushroom
            dw    %0000   ; to castle_bowser
BG_UPDATE_MASKS_GROUND_SNOW
            dw    $0000
            dw    %0000   ; to ground
            dw    %0010   ; to underground
            dw    %0000   ; to water
            dw    %0000   ; to castle
            dw    %0000   ; to ground_snow
            dw    %0000   ; to ground_mushroom
            dw    %0000   ; to castle_bowser
BG_UPDATE_MASKS_GROUND_MUSHROOM
            dw    $0000
            dw    %0000   ; to ground
            dw    %0010   ; to underground
            dw    %0000   ; to water
            dw    %0000   ; to castle
            dw    %0000   ; to ground_snow
            dw    %0000   ; to ground_mushroom
            dw    %0000   ; to castle_bowser
BG_UPDATE_MASKS_CASTLE_BOWSER
            dw    $0000
            dw    %0000   ; to ground
            dw    %0010   ; to underground
            dw    %0000   ; to water
            dw    %0000   ; to castle
            dw    %0000   ; to ground_snow
            dw    %0000   ; to ground_mushroom
            dw    %0000   ; to castle_bowser
